"""Group homepage, carrying the Recovery site's visual and commercial clarity."""
from html import escape


def render_home(businesses, photograph, link):
    offers = {
        "recovery": ("Freight audit & recovery", "Find the overcharges. Follow the evidence.", "Start a free audit", "<strong>$0</strong> upfront audit fee", '<img class="editorial-photo" src="/assets/images/terminal-blue-hour-800.webp" width="800" height="500" alt="Freight terminal at blue hour" loading="lazy" decoding="async">'),
        "capturebrief": ("Federal opportunity research", "See the opportunity. Understand the decision.", "Explore CaptureBrief", "<strong>$149</strong> / one review", photograph("research", "Research notebooks and a laptop in a sunlit workspace")),
        "permitplate": ("NYC restaurant intelligence", "Find the projects. Plan your next conversation.", "Explore PermitPlate", "<strong>$79</strong> / month", photograph("restaurant", "Illustrative New York corner restaurant with green window frames")),
    }
    featured = ""
    for b in businesses[:3]:
        category, headline, action, price, photo = offers[b["slug"]]
        featured += f'''<a class="business-card featured-card" href="/{b['slug']}/"><div class="card-image">{photo}<span class="photo-label">{escape(category)}</span></div><div class="card-copy"><p class="group-kicker">{escape(b['name'])}</p><h3>{headline}</h3><p>{escape(b['summary'])}</p><p class="featured-price">{price}</p><div class="card-bottom"><span>{action}</span><span aria-hidden="true">↗</span></div></div></a>'''
    routes = (("recovery", "Recover freight overcharges", "Free audit · approved recovery"), ("capturebrief", "Assess a federal opportunity", "$149 · one focused review"), ("permitplate", "Track NYC restaurant projects", "$79/month · weekly research"))
    quicklinks = "".join(f'<a href="/{slug}/"><span><strong>{label}</strong><small>{note}</small></span><span aria-hidden="true">↗</span></a>' for slug, label, note in routes)
    anchors = {"rehabsignal": "division-2", "sheetharbor": "division-3", "scopesignal": "division-4"}
    studio = ""
    for b in businesses[3:]:
        anchor = f' id="{anchors[b["slug"]]}"' if b["slug"] in anchors else ""
        studio += f'''<a class="portfolio-item"{anchor} href="/{b['slug']}/"><p class="portfolio-category">{escape(b['division'])}</p><h3>{escape(b['name'])}<span aria-hidden="true">↗</span></h3><p>{escape(b['summary'])}</p><span class="group-status">{escape(b['status'])}</span></a>'''
    hero = photograph("hero", "Illustrative business research studio overlooking a city at blue hour", eager=True).replace('sizes="(max-width: 760px) calc(100vw - 40px), 600px"', 'sizes="100vw"')
    return f'''<section class="group-hero flagship-hero" aria-labelledby="group-title"><div class="home-backdrop">{hero}</div><div class="group-wrap group-hero-grid"><div class="hero-intro"><p class="group-kicker">RECOVERY · RESEARCH · PRACTICAL TOOLS</p><h1 id="group-title">Find the value.<br><em>Move forward.</em></h1><p class="group-lead">Recover freight overcharges. Research your next opportunity. Put clearer evidence behind your business decisions.</p><div class="group-actions">{link("Explore our businesses", "#businesses", "group-button")}{link("Talk to RETALLY", "/contact/", "group-button button-outline")}</div><p class="group-hero-note">Focused expertise. Clear scope. A practical next step.</p></div><aside class="hero-console" aria-label="Find your starting point"><div class="console-heading"><p class="group-kicker">AVAILABLE TODAY</p><span class="console-count">03 offers</span></div><h2>What would you like to move forward with?</h2><div class="console-links">{quicklinks}</div><a class="console-help" href="/contact/">Not sure where to start? Talk to us <span aria-hidden="true">↗</span></a></aside></div></section>
<div class="group-principles"><div class="group-wrap"><span>Evidence before claims</span><span>Human judgment where it matters</span><span>Clear scope from the start</span></div></div>
<section class="group-section group-wrap" id="businesses"><div class="section-title-row"><div><p class="group-kicker">OUR BUSINESSES</p><h2>Expertise with<br><em>a clear purpose.</em></h2></div><p>Three focused offers, available today.<br>Choose the problem you need to solve.</p></div><div class="featured-grid" id="division-1">{featured}</div></section>
<section class="group-approach" id="approach"><div class="group-wrap approach-layout"><figure class="approach-photo">{photograph("research", "Detailed research materials in a naturally lit workspace")}<figcaption><span class="photo-caption-label">THE RETALLY STANDARD</span><strong>Look closer.<br>Make the next step count.</strong></figcaption></figure><div><p class="group-kicker">HOW WE WORK</p><h2>Good decisions start<br><em>with clear evidence.</em></h2><p class="approach-intro">Every RETALLY business begins with a specific problem and a practical way forward.</p><ol class="approach-steps"><li><span>01</span><div><h3>Understand the problem</h3><p>Start with the question you need to answer and the outcome you’re working toward.</p></div></li><li><span>02</span><div><h3>Make the work clear</h3><p>Review the scope, source material and deliverable before you commit.</p></div></li><li><span>03</span><div><h3>Move forward with context</h3><p>See what the evidence supports, where the limits are and what comes next.</p></div></li></ol></div></div></section>
<section class="studio-section" id="studio"><div class="group-wrap"><div class="section-title-row"><div><p class="group-kicker">MORE FROM RETALLY</p><h2>Ideas becoming<br><em>useful businesses.</em></h2></div><p>Explore tools, previews and research.<br>Each business shows its current stage.</p></div><div class="studio-grid">{studio}</div></div></section>
<section class="group-wrap next-step-panel"><div><p class="group-kicker">LET’S FIND YOUR STARTING POINT</p><h2>Bring us the problem.<br><em>We’ll help you find the way in.</em></h2></div>{link("Start a conversation", "/contact/", "group-button")}</section>'''
